const API="",token=localStorage.getItem("token");token||(window.location.href="/static/login.html?next=/admin");const headers={"Content-Type":"application/json",Authorization:"Bearer "+token},statsGrid=document.getElementById("admin-stats-grid"),usersTableBody=document.querySelector("#admin-users-table tbody"),chatsTableBody=document.querySelector("#admin-chats-table tbody"),messagesTableBody=document.querySelector("#admin-messages-table tbody"),bugReportsContainer=document.getElementById("admin-bug-reports"),logoutBtn=document.getElementById("admin-logout-btn");function escapeHtml(t){return String(t??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")}function formatDate(t){return t?t.replace("T"," ").slice(0,19):"—"}function truncate(t,e=160){const a=String(t??"");return a.length>e?a.slice(0,e-1)+"…":a}function renderOverview(t){const e=[["Пользователи",t.users_total],["Чаты",t.chats_total],["Сообщения",t.messages_total],["Ошибки",t.bug_reports_total],["Запросы за 30 дней",t.requests_30d],["Активные юзеры за 30 дней",t.active_users_30d]];statsGrid.innerHTML=e.map(([t,e])=>`\n        <article class="admin-stat-card">\n            <div class="admin-stat-value">${escapeHtml(e)}</div>\n            <div class="admin-stat-label">${escapeHtml(t)}</div>\n        </article>\n    `).join("")}function renderUsers(t){usersTableBody.innerHTML=t.map(t=>`\n        <tr>\n            <td>${t.id}</td>\n            <td>${escapeHtml(t.email)}</td>\n            <td>${escapeHtml(t.plan)}</td>\n            <td>${t.requests_remaining??Math.max(0,t.requests_limit-t.requests_30d)}</td>\n            <td>${t.chats_count}</td>\n            <td>${t.messages_count}</td>\n            <td>${t.requests_30d}</td>\n            <td>${t.bug_reports_count}</td>\n            <td>${escapeHtml(formatDate(t.last_message_at))}</td>\n            <td>${escapeHtml(formatDate(t.created_at))}</td>\n        </tr>\n    `).join("")}function renderChats(t){chatsTableBody.innerHTML=t.map(t=>`\n        <tr>\n            <td>${t.id}</td>\n            <td>${escapeHtml(t.email)}</td>\n            <td title="${escapeHtml(t.title)}">${escapeHtml(truncate(t.title,40))}</td>\n            <td>${t.messages_count}</td>\n            <td>${escapeHtml(formatDate(t.created_at))}</td>\n        </tr>\n    `).join("")}function renderMessages(t){messagesTableBody.innerHTML=t.map(t=>`\n        <tr>\n            <td>${t.id}</td>\n            <td>${escapeHtml(t.email)}</td>\n            <td title="${escapeHtml(t.chat_title||"")}">#${t.chat_id}</td>\n            <td>${escapeHtml(t.role)}</td>\n            <td title="${escapeHtml(t.text)}">${escapeHtml(truncate(t.text,180))}</td>\n            <td>${escapeHtml(formatDate(t.created_at))}</td>\n        </tr>\n    `).join("")}function renderBugReports(t){t.length?bugReportsContainer.innerHTML=t.map(t=>`\n        <article class="admin-card">\n            <div class="admin-card-meta">\n                <strong>#${t.id}</strong>\n                <span>${escapeHtml(t.email)}</span>\n                <span>${escapeHtml(formatDate(t.created_at))}</span>\n            </div>\n            <div class="admin-card-text">${escapeHtml(t.text)}</div>\n            <div class="admin-card-foot">\n                <span>chat_id: ${t.chat_id??"—"}</span>\n                <span title="${escapeHtml(t.page_url||"")}">${escapeHtml(truncate(t.page_url||"—",60))}</span>\n            </div>\n        </article>\n    `).join(""):bugReportsContainer.innerHTML='<div class="admin-empty">Пока нет сообщений об ошибках.</div>'}async function loadAdminDashboard(){const t=await fetch("/api/me",{headers:headers});if(401===t.status)return void logout();if(!(await t.json()).is_admin)return void(document.body.innerHTML='<div class="admin-denied">Недостаточно прав для доступа к админ-панели.</div>');const e=await fetch("/api/admin/dashboard",{headers:headers});if(!e.ok)return void(document.body.innerHTML='<div class="admin-denied">Не удалось загрузить админ-данные.</div>');const a=await e.json();renderOverview(a.overview),renderUsers(a.users),renderChats(a.recent_chats),renderMessages(a.recent_messages),renderBugReports(a.bug_reports)}function logout(){localStorage.removeItem("token"),localStorage.removeItem("email"),window.location.href="/static/login.html?next=/admin"}logoutBtn.addEventListener("click",logout),loadAdminDashboard();